// Worker entry (wrangler.jsonc "main"). Wraps the OpenNext handler with Cloudflare's edge cache. Pages are rendered from the
// database on request, so without this every visit would run Next.js and a database query. A cache hit costs almost no CPU,
// which is what keeps the free plan (10 ms CPU per request) clear of error 1102.
//
// IMPORTANT: Cloudflare's Cache API only works on a CUSTOM DOMAIN. On *.workers.dev it silently does nothing.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as openNext } from "./.open-next/worker.js";

// The Durable Object classes OpenNext declares must be re-exported from the entry module.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

type Ctx = { waitUntil(promise: Promise<unknown>): void };
type Env = { CF_VERSION_METADATA?: { id?: string } };

/** Public pages: browsers always revalidate; the edge keeps a page for 5 minutes and may serve a stale copy for an hour. A publish is therefore live within ~5 minutes. */
const PAGE_CACHE_CONTROL = "public, max-age=0, s-maxage=300, stale-while-revalidate=3600";

/** A second, long-lived copy of each page. It is only ever served when rendering fails (database down, quota hit, Worker error), so readers see the last good page instead of an error. */
const STALE_CACHE_CONTROL = "public, max-age=86400";

// Never cached: the admin area, API routes, framework internals, and the Cloudflare image endpoints.
const SKIP = /^\/(admin|api|_next|cdn-cgi)(\/|$)/;
// Uploaded images are content-addressed and immutable; they keep the one-year header the route already sets.
const MEDIA = /^\/media\//;

const worker = {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    const url = new URL(request.url);
    const cacheable = request.method === "GET" && !request.headers.has("range") && !request.headers.has("authorization") && !SKIP.test(url.pathname);
    if (!cacheable) return openNext.fetch(request, env, ctx);

    // One cache entry per URL (query string included: search pages use it) and per deployment, so a new deploy never serves old HTML.
    const cache = (caches as unknown as { default: Cache }).default;
    const version = env.CF_VERSION_METADATA?.id;
    const keyUrl = new URL(request.url);
    if (version) keyUrl.searchParams.set("__v", version);
    const cacheKey = new Request(keyUrl.toString(), { method: "GET" });

    const hit = await cache.match(cacheKey);
    if (hit) return hit;

    const staleKey = new Request(`${keyUrl.toString()}${keyUrl.search ? "&" : "?"}__stale=1`, { method: "GET" });
    const serveStale = async (): Promise<Response | null> => {
      const old = await cache.match(staleKey);
      if (!old) return null;
      const r = new Response(old.body, old);
      r.headers.set("Cache-Control", "public, max-age=0, s-maxage=60");
      r.headers.set("X-Served-Stale", "1");
      return r;
    };

    let response: Response;
    try {
      response = await openNext.fetch(request, env, ctx);
    } catch (e) {
      const old = await serveStale();
      if (old) return old;
      throw e;
    }
    if (response.status >= 500) return (await serveStale()) ?? response;
    if (response.status !== 200 || response.headers.has("set-cookie")) return response;
    const type = response.headers.get("content-type") ?? "";
    const isMedia = MEDIA.test(url.pathname) && type.startsWith("image/");
    const isPage = /text\/html|application\/(rss\+)?xml/.test(type);
    if (!isMedia && !isPage) return response;

    const cached = new Response(response.body, response);
    if (isPage) cached.headers.set("Cache-Control", PAGE_CACHE_CONTROL);
    ctx.waitUntil(
      Promise.all([
        cache.put(cacheKey, cached.clone()),
        isPage
          ? (() => {
              const keep = new Response(cached.clone().body, cached);
              keep.headers.set("Cache-Control", STALE_CACHE_CONTROL);
              return cache.put(staleKey, keep);
            })()
          : Promise.resolve(),
      ]),
    );
    return cached;
  },
};

export default worker;
